use serde_json::{Value,json};
use crate::semantic::task::generation::{ContentPart,GenerationRequest,InstructionAuthority,Item,MessageRole};
pub fn encode_generation(r:&GenerationRequest)->Value{let mut input=Vec::new();for(_,i)in r.items(){match i{Item::Instruction(x)=>input.push(json!({"role":match x.authority{InstructionAuthority::System=>"system",InstructionAuthority::Developer=>"developer"},"content":x.text.as_str()})),Item::Message(m)=>{let c=m.parts.iter().map(|p|match &p.content{ContentPart::Text(t)=>json!({"type":if m.role==MessageRole::User{"input_text"}else{"output_text"},"text":t.as_str()})}).collect::<Vec<_>>();input.push(json!({"role":match m.role{MessageRole::User=>"user",MessageRole::Assistant=>"assistant"},"content":c}))}}}let mut v=json!({"input":input});let o=v.as_object_mut().unwrap();if let Some(x)=r.controls().max_output_tokens{o.insert("max_output_tokens".into(),json!(x));}if let Some(x)=r.controls().temperature(){o.insert("temperature".into(),json!(x));}v}
